#!/bin/bash
set -euo pipefail

# Passwords generated by bootstrap contain only letters/digits; reject SQL metacharacters.
if [[ ! "${PC_RUNTIME_PASSWORD:-}" =~ ^[a-zA-Z0-9]{16,}$ ]]; then
  echo 'PC_RUNTIME_PASSWORD must have at least 16 alphanumeric characters.' >&2
  exit 1
fi

sqlplus -s / as sysdba <<SQL
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
ALTER SESSION SET CONTAINER = FREEPDB1;
CREATE USER PC_APP IDENTIFIED BY "${PC_RUNTIME_PASSWORD}";
GRANT CREATE SESSION TO PC_APP;
EXIT;
SQL
